	writeJSONHTTP(w, http.StatusOK, resp)
}"},{"rank":4,"score":45.731,"file_path":"internal/cli/workspace.go","start_line":1808,"end_line":1824,"focus_line":1808,"snippet_start_line":1808,"snippet_end_line":1824,"symbol_start_line":1808,"symbol_end_line":1824,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/workspace.go:function:sortWorkspaceGraphSymbolRefs","symbol_name":"sortWorkspaceGraphSymbolRefs","qualified_name":"sortWorkspaceGraphSymbolRefs","signature":"func sortWorkspaceGraphSymbolRefs(refs []workspaceGraphSymbolRef)","signals":["graph:calls","graph:outgoing","graph:callers","complete-symbol"],"snippet":"func sortWorkspaceGraphSymbolRefs(refs []workspaceGraphSymbolRef) {
