				edges = append(edges, workspaceGraphCrossEdge{
					Endpoint:     endpoint,
					Type:         "CALLS",
					FromRepo:     caller.RepoKey,
					ToRepo:       handler.RepoKey,
					FromSymbol:   caller,
					ToSymbol:     handler,
					SharedCount:  caller.Count + handler.Count,
					RelationKind: "cross_repo_route_call",
				})
			}
		}
	}
