}"},{"rank":3,"score":45.1947,"file_path":"internal/cli/viz.go","start_line":1217,"end_line":1343,"focus_line":1217,"snippet_start_line":1217,"snippet_end_line":1343,"symbol_start_line":1217,"symbol_end_line":1343,"language":"Go","kind":"method","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/viz.go:method:vizServer.handleGraph","symbol_name":"handleGraph","qualified_name":"vizServer.handleGraph","signature":"func (s *vizServer) handleGraph(w http.ResponseWriter, r *http.Request)","signals":["path","body","symbol-name","complete-symbol"],"snippet":"func (s *vizServer) handleGraph(w http.ResponseWriter, r *http.Request) {
