func TestVizHandleDocs_PrefixedIDsMatchSearch(t *testing.T) {
	t.Parallel()
	brainDir := t.TempDir()
	idx := docIndex{Records: []docRecord{
		{ID: "abc123", Path: "docs/a.md", Heading: "A", Line: 1, Text: "alpha"},
		{ID: "def456", Path: "docs/a.md", Heading: "B", Line: 9, Text: "beta"},
	}}
